package ru.wibestyle.api.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="hairstyle_catalog") public class HairstyleCatalogEntity {
 @Id private UUID id; @Column(nullable=false,unique=true) private String slug; @Column(nullable=false) private String title; @Column(nullable=false,length=600) private String description; @Column(name="hair_type",nullable=false) private String hairType; @Column(name="master_note",nullable=false,length=600) private String masterNote; @Column(name="ai_directive",nullable=false,length=600) private String aiDirective; @Column(name="image_path",nullable=false) private String imagePath; @Column(name="sort_order",nullable=false) private int sortOrder; @Column(nullable=false) private boolean active=true; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected HairstyleCatalogEntity(){} public HairstyleCatalogEntity(UUID id,String slug,String title,String description,String type,String note,String directive,String path,int sort,Instant now){this.id=id;this.slug=slug;this.title=title;this.description=description;hairType=type;masterNote=note;aiDirective=directive;imagePath=path;sortOrder=sort;createdAt=now;updatedAt=now;}
 public UUID getId(){return id;} public String getSlug(){return slug;} public String getTitle(){return title;} public String getDescription(){return description;} public String getHairType(){return hairType;} public String getMasterNote(){return masterNote;} public String getAiDirective(){return aiDirective;} public String getImagePath(){return imagePath;} public int getSortOrder(){return sortOrder;} public boolean isActive(){return active;} public void update(String title,String description,String type,String note,String directive,int sort,boolean active){this.title=title;this.description=description;hairType=type;masterNote=note;aiDirective=directive;sortOrder=sort;this.active=active;updatedAt=Instant.now();} public void setImagePath(String path){imagePath=path;updatedAt=Instant.now();}
}
